#include <cstdint>
#include <cassert>

// Simulate Slice class
class Slice {
 public:
  Slice() : data_(""), size_(0) {}
  Slice(const char* d, size_t n) : data_(d), size_(n) {}
  const char* data() const { return data_; }
  size_t size() const { return size_; }
  void remove_prefix(size_t n) {
    assert(n <= size_);
    data_ += n;
    size_ -= n;
  }
 private:
  const char* data_;
  size_t size_;
};

namespace leveldb {

bool GetVarint64(Slice* input, uint64_t* value) {
  const char* p = input->data();
  const char* limit = input->data() + input->size();
  uint64_t result = 0;

  for (int shift = 0; shift <= 63; shift += 7) {
    if (p >= limit) {
      return false;  // Ran out of bytes
    }

    uint64_t byte = static_cast<unsigned char>(*p);
    p++;

    result |= (byte & 0x7F) << shift;

    if ((byte & 0x80) == 0) {
      // No continuation bit, we're done
      *value = result;
      input->remove_prefix(p - input->data());
      return true;
    }
  }

  return false;  // Varint64 too long (more than 10 bytes)
}

}  // namespace leveldb

// Test
#include <iostream>
int main() {
    // Test case 1: Single byte varint (value = 1)
    const char buf1[] = {0x01};
    Slice s1(buf1, 1);
    uint64_t v1 = 0;
    bool ok1 = leveldb::GetVarint64(&s1, &v1);
    std::cout << "Test 1: ok=" << ok1 << " value=" << v1 << " remaining=" << s1.size() << std::endl;

    // Test case 2: Two byte varint (value = 300)
    // 300 = 0x12C = 0b10101100 shifted
    // Encoded as: 0xAC 0x02 (little endian 7-bit groups)
    const char buf2[] = {0xAC, 0x02};
    Slice s2(buf2, 2);
    uint64_t v2 = 0;
    bool ok2 = leveldb::GetVarint64(&s2, &v2);
    std::cout << "Test 2: ok=" << ok2 << " value=" << v2 << " remaining=" << s2.size() << std::endl;

    // Test case 3: Max int64 (all 10 bytes with continuation bits except last)
    // 0xFFFFFFFFFFFFFFFF encoded
    const char buf3[] = {0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0x01};
    Slice s3(buf3, 10);
    uint64_t v3 = 0;
    bool ok3 = leveldb::GetVarint64(&s3, &v3);
    std::cout << "Test 3: ok=" << ok3 << " value=" << v3 << " remaining=" << s3.size() << std::endl;

    return 0;
}

